// ─── Template sanitisation ────────────────────────────────────────────────────

/**
 * Matches a single Nunjucks-style template construct: an opening delimiter
 * (`{{` or `{%`) followed lazily by any characters that do not themselves start
 * a new opening delimiter, up to the next closing delimiter (`}}` or `%}`).
 *
 * Allowing either closing delimiter to terminate either opening delimiter is
 * deliberate: it prevents template injection via interleaved delimiters (e.g.
 * `{{ {% ... %} }}` or `{% {{ ... }} %}`). The negative lookahead ensures an
 * inner construct is consumed before the outer one, so nested tags collapse
 * from the inside out across repeated passes. Because a match always requires a
 * closing delimiter, an unpaired opening delimiter is left untouched.
 */
const TEMPLATE_TAG = /(?:\{\{|\{%)(?:(?!\{\{|\{%)[\s\S])*?(?:\}\}|%\})/g;

/** Removes all Nunjucks-style template constructs from a string, keeping surrounding text. */
function stripTemplateTags(input: string): string {
  let result = input;
  let previous: string;
  // Loop so nested constructs revealed by an inner removal are stripped too.
  do {
    previous = result;
    result = result.replace(TEMPLATE_TAG, '');
  } while (result !== previous);
  return result;
}

/**
 * Returns a new route with every Nunjucks-style template expression removed from
 * its string fields, guarding against secret leakage / template injection when a
 * route is synced to Konnect.
 *
 * - `name`, `expression`: template constructs stripped, surrounding text kept.
 * - `paths`, `hosts`: each entry stripped, surrounding text kept.
 * - `methods`: each entry stripped; entries that strip to empty are dropped; if
 *   nothing remains the field becomes `null`.
 * - `headers`: each value stripped and empties dropped; a header whose values
 *   all vanish, or whose name strips to empty, is dropped entirely.
 * - `null` values pass through as `null`.
 * - Non-string fields (`id`, `protocols`, `snis`, `service`) are passed through.
 */
export function sanitizeRoute(route: KonnectRoute): KonnectRoute {
  const methods = route.methods === null
    ? null
    : (() => {
        const kept = route.methods.map(stripTemplateTags).filter(m => m !== '');
        return kept.length === 0 && route.methods.length > 0 ? null : kept;
      })();

  let headers: Record<string, string[]> | null = null;
  if (route.headers !== null) {
    headers = {};
    for (const [name, values] of Object.entries(route.headers)) {
      const strippedName = stripTemplateTags(name);
      if (strippedName === '') { continue; }
      const strippedValues = values.map(stripTemplateTags).filter(v => v !== '');
      if (strippedValues.length === 0) { continue; }
      headers[strippedName] = strippedValues;
    }
  }

  return {
    ...route,
    name: route.name === null ? null : stripTemplateTags(route.name),
    methods,
    paths: route.paths === null ? null : route.paths.map(stripTemplateTags),
    hosts: route.hosts === null ? null : route.hosts.map(stripTemplateTags),
    headers,
